    OptGroup: OptGroup renders a native optgroup around option children.
    Props (p): Class (string), Label (string), Disabled (bool), Attrs (attrs); children: markup. *}
<optgroup
  class="{=ui_cn([($p['Class'] ?? '')])}"
  {if ui_is_set_str(($p['Label'] ?? ''))} label="{=($p['Label'] ?? '')}"{/if}
  {if ($p['Disabled'] ?? false)} disabled{/if}
  {=ui_attr_html(($p['Attrs'] ?? []))|noescape}
>{=($children ?? '')|noescape}</optgroup>

{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/ui/select.json
    SelectOption: SelectOption renders an option for custom Select children.
    Props (p): Value (string), Label (string), Selected (bool), Disabled (bool), Attrs (attrs); children: markup. *}
<option
  {if ui_is_set_str(($p['Value'] ?? ''))} value="{=($p['Value'] ?? '')}"{/if}
  {if ui_is_set_str(($p['Label'] ?? ''))} label="{=($p['Label'] ?? '')}"{/if}
  {if ($p['Selected'] ?? false)} selected{/if}
  {if ($p['Disabled'] ?? false)} disabled{/if}
  {=ui_attr_html(($p['Attrs'] ?? []))|noescape}
>{=($children ?? '')|noescape}</option>

{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/ui/select.json
    Select: Select renders option children from the Options list plus manual children.
    Props (p): Variant (string), Size (string), Class (string), Name (string), Value (string), Disabled (bool), Required (bool), Options (SelectOptionItem[]), ID (string), Role (string), TabIndex (string), AriaLabel (string), Attrs (attrs); children: markup. *}
<select
  {if ui_is_set_str(($p['ID'] ?? ''))} id="{=($p['ID'] ?? '')}"{/if}
  {if ui_is_set_str(($p['Name'] ?? ''))} name="{=($p['Name'] ?? '')}"{/if}
  class="{=ui_compose('ui/select/select.variants.json', ['size' => ($p['Size'] ?? ''), 'variant' => ($p['Variant'] ?? '')], [($p['Class'] ?? '')])}"
  {if ($p['Disabled'] ?? false)} disabled{/if}
  {if ($p['Required'] ?? false)} required{/if}
  {if ui_is_set_str(($p['Role'] ?? ''))} role="{=($p['Role'] ?? '')}"{/if}
  {if ui_is_set_str(($p['TabIndex'] ?? ''))} tabindex="{=($p['TabIndex'] ?? '')}"{/if}
  {if ui_is_set_str(($p['AriaLabel'] ?? ''))} aria-label="{=($p['AriaLabel'] ?? '')}"{/if}
  {=ui_attr_html(($p['Attrs'] ?? []))|noescape}
>
  {foreach ($p['Options'] ?? []) as $item}
    <option
      value="{=ui_field($item, 'Value', '')}"
      {if ui_eq(ui_field($item, 'Value', ''), ($p['Value'] ?? ''))} selected{/if}
    >{=ui_field($item, 'Label', '')}</option>
  {/foreach}
  {=($children ?? '')|noescape}
</select>

